export const SPINNER_HTML = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, user-scalable=no"><style>*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }html, body {  width: 100%; height: 100%;  background: transparent;  display: flex;  align-items: center;  justify-content: center;  overflow: hidden;}.spinner {  width: min(28vmin, 220px);  aspect-ratio: 1 / 1;  animation: spin 2.4s linear infinite;}.spinner img {  width: 100%; height: 100%;  display: block;  animation: pulse 2.4s linear infinite;}@keyframes spin { 0% { transform: rotate(0deg); animation-timing-function: ease-in; } 25% { transform: rotate(140deg); animation-timing-function: ease-out; } 50% { transform: rotate(180deg); animation-timing-function: ease-in; } 75% { transform: rotate(320deg); animation-timing-function: ease-out; } 100% { transform: rotate(360deg); } }@keyframes pulse {  0% { filter: drop-shadow(0 0 2px rgba(255,255,255,0.0)); opacity: 0.45; }  25% { filter: drop-shadow(0 0 14px rgba(255,255,255,0.9)) drop-shadow(0 0 32px rgba(255,255,255,0.5)); opacity: 1; }  50% { filter: drop-shadow(0 0 2px rgba(255,255,255,0.0)); opacity: 0.45; }  75% { filter: drop-shadow(0 0 14px rgba(255,255,255,0.9)) drop-shadow(0 0 32px rgba(255,255,255,0.5)); opacity: 1; }  100% { filter: drop-shadow(0 0 2px rgba(255,255,255,0.0)); opacity: 0.45; }}body.light .spinner img { animation: pulse-dark 2.4s linear infinite; }@keyframes pulse-dark {  0% { filter: invert(1) drop-shadow(0 0 2px rgba(0,0,0,0)); opacity: 0.55; }  25% { filter: invert(1) drop-shadow(0 0 14px rgba(0,0,0,0.9)) drop-shadow(0 0 32px rgba(0,0,0,0.5)); opacity: 1; }  50% { filter: invert(1) drop-shadow(0 0 2px rgba(0,0,0,0)); opacity: 0.55; }  75% { filter: invert(1) drop-shadow(0 0 14px rgba(0,0,0,0.9)) drop-shadow(0 0 32px rgba(0,0,0,0.5)); opacity: 1; }  100% { filter: invert(1) drop-shadow(0 0 2px rgba(0,0,0,0)); opacity: 0.55; }}@media (prefers-reduced-motion: reduce) { .spinner, .spinner img { animation-duration: 18s; } }</style></head><body class=\"light\"><div class="spinner"><img src="data:image/png;base64," alt=""></div><script>window.addEventListener("message", function(e) {  if (e.data === "dark")  document.body.classList.remove("light");  if (e.data === "light") document.body.classList.add("light");});</script></body></html>';